*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "btn_downloadFile", fn: function () { return String(dlt_attachList.getCellData(0, "attachFileNm")); } },
        { childId: "btn_downloadFile_2", fn: function () { return String(dlt_attachList.getCellData(0, "attachFileNm")); } },
        { childId: "btn_downloadFile_3", fn: function () { return String(dlt_attachList.getCellData(1, "attachFileNm")); } },
        { childId: "btn_downloadFile_4", fn: function () { return String(dlt_attachList.getCellData(1, "attachFileNm")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

