    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isCheckMonth
 * @author Inswave
 * @date 2026. 09. 29
 * @param month
 * @returns
 * @hidden N
*/
scwin.isCheckMonth = function (month) {
    /* sdd-asis-lifecycle:begin isCheckMonth — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const checkMonth = new Array("2", "4", "6", "8", "10");
    for (let i = 0; i < checkMonth.length; i++) {
        if (month === checkMonth[i]) {
            return i;
        }
    }
    return -1;
    /* sdd-asis-lifecycle:end */
};


