/**
 * @method
 * @name scwin.checkValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkValue = async function () {
    /* sdd-asis-lifecycle:begin checkValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_doSaveReq').set('bzRegNo', $c.util.getComponent('ipt_bzRegNo1').getValue()+ $c.util.getComponent('ipt_bzRegNo2').getValue()+ $c.util.getComponent('ipt_bzRegNo3').getValue());
    if (($c.util.getComponent('ipt_chkCd').getValue() == null ? '' : String($c.util.getComponent('ipt_chkCd').getValue())) === '') {
        await $c.win.alert('발행기관을 선택하셔야 합니다.');
        return false;
    }
    if (($c.util.getComponent('slc_ldMktTpCd').getValue() == null ? '' : String($c.util.getComponent('slc_ldMktTpCd').getValue())) === '') {
        await $c.win.alert('상장시장을 선택하셔야 합니다.');
        return false;
    }
    if (!await scwin.checkListAgnccomMbrNo()) {
        return false;
    }
    for (let i = 0; i < $c.util.getComponent('slc_secugrpId').length; i++) {
        if ($c.util.getComponent('slc_secugrpId')[i].selected === true) {
            if (i == 0) {
                await $c.win.alert('증권그룹을 선택하셔야 합니다.');
                return false;
            }
        }
    }
    $c.util.getComponent('dma_doSaveReq').set('acntclsMmdd', $c.util.getComponent('slc_acntclsMm').getValue()+ $c.util.getComponent('slc_acntclsDd').getValue());
    $c.util.getComponent('dma_doSaveReq').set('skilValuSpeclYn', scwin.getCheckBoxValue($c.util.fieldEl('ipt_chkSkilValuSpeclYn', 'chkSkilValuSpeclYn')));
    $c.util.getComponent('dma_doSaveReq').set('grwthRecmndYn', scwin.getCheckBoxValue($c.util.fieldEl('ipt_chkGrwthRecmndYn', 'chkGrwthRecmndYn')));
    return true;
    /* sdd-asis-lifecycle:end */
};


