async function checkListAgnccom(cObj) {
    /* sdd-asis-lifecycle:begin checkListAgnccom — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = form[cObj.name];
    const len = obj.length;
    if (len < 40) {
        for (let i = 0; i < len; i++) {
            if (obj[i] !== cObj) {
                if (obj[i].value === cObj.value) {
                    await $c.win.alert('이미 선택하신 상장주선인 입니다.');
                    cObj.value = '';
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
}

